const MAINTENANCE_HTML="";
const REFRESH_RUNNER="";
// Reuse the public site's keyword search, including its assigned-manager matching.
// Only vehicle IDs are returned. Prices always come from the saved pricing basis.
const inventorySearchCache = new Map();
async function inventorySearchResponse(url, env, ctx, signal) {
 const query = (url.searchParams.get('q') || '').trim();
 if (query.length < 2 || query.length > 40) {
  return Response.json({error:'검색어는 2~40자로 입력해 주세요.'}, {status:400});
 }
 try {
  const data = await fastInventory(env, ctx);
  const key = JSON.stringify([data.checkedAt, query.toLowerCase()]);
  let cached = inventorySearchCache.get(key);
  if (!cached || cached.expiresAt <= Date.now()) {
   const ids = new Set();
   let total = null;
   for (let page = 1; page <= 30; page++) {
    const params = new URLSearchParams({perPageNum:'100', page:String(page), saleTyRent:'true', orderType:'regDt', keyword:query});
    const response = await fetch(BASE + '/cr/search/ajax/list?' + params, {signal:requestSignal(8000, signal)});
    if (!response.ok) throw Error('Search unavailable');
    const {result} = await response.json();
    if (!Array.isArray(result?.data) || !Number.isInteger(Number(result.recordsFiltered)) || Number(result.recordsFiltered) < 0) throw Error('Invalid search');
    total = Number(result.recordsFiltered);
    for (const car of result.data) if (/^\d+$/.test(String(car.carId))) ids.add(String(car.carId));
    if (ids.size >= total) break;
    if (!result.data.length) throw Error('Incomplete search');
   }
   if (ids.size !== total) throw Error('Incomplete search');
   cached = {ids:[...ids], expiresAt:Date.now() + 300000};
   if (inventorySearchCache.size >= 100) inventorySearchCache.delete(inventorySearchCache.keys().next().value);
   inventorySearchCache.set(key, cached);
  }
  const active = new Set(data.cars.map(car => String(car.id)));
  return Response.json({query, ids:cached.ids.filter(id => active.has(id))}, {headers:{'Cache-Control':'no-store'}});
 } catch {
  return Response.json({error:'매니저 검색을 완료하지 못했습니다. 잠시 후 다시 검색해 주세요.'}, {status:502});
 }
}

// The official popup reads the full list with an anonymous session and no model filter.
async function fetchUpcomingCars(){
 const page=await fetch(BASE+'/view/main',{signal:AbortSignal.timeout(10000)});
 if(!page.ok)throw Error('입고 공지 페이지 조회 실패');
 const html=await page.text();
 const token=html.match(/<meta[^>]*(?:id|name)="_csrf"[^>]*content="([^"]+)"/)?.[1];
 if(!token)throw Error('입고 공지 세션 확인 실패');
 const result=await fetch(BASE+'/cr/search/ajax/upcomingCarInboundList',{
  method:'POST',signal:AbortSignal.timeout(10000),
  headers:{'X-Requested-With':'XMLHttpRequest','X-CSRF-TOKEN':token,'Cookie':sourceCookies(page.headers)}
 });
 if(!result.ok)throw Error('입고 공지 조회 실패');
 const data=await result.json();
 if(data.status!=='OK'||!Array.isArray(data.list))throw Error('입고 공지 형식 확인 필요');
 const cars=data.list.map(row=>{
  if(!row?.modelName||!row.modelNumber)throw Error('입고 차량 정보 확인 필요');
  return {name:row.modelName,plate:row.modelNumber,year:row.modelYear||'',fuel:row.fuel||'',
   mileage:row.mileage!=null&&row.mileage!==''&&Number.isFinite(Number(row.mileage))?Number(row.mileage):null};
 });
 return {checkedAt:new Date().toISOString(),cars};
}

