 try{conditions=parseConditions(url.searchParams);if(!conditions||ids.length>6||!ids.length||new Set(ids).size!==ids.length||ids.some(id=>!/^\d{1,10}$/.test(id)))throw Error('Invalid batch')}catch{return Response.json({error:'Invalid batch'},{status:400})}
 const encoder=new TextEncoder(),code=priceCode(conditions),results=[],abort=new AbortController();let stopped=false;
