 const body=new ReadableStream({start(controller){const work=Promise.all(ids.map(async id=>{let q;try{q=await cachedQuote(id,conditions,env,ctx,false,abort.signal);results.push(q)}catch{q={id,status:'error',price:null,code,conditions,term:Number(conditions.term),checkedAt:new Date().toISOString()}}if(!stopped){try{controller.enqueue(encoder.encode(JSON.stringify(q)+'\n'))}catch{stopped=true;abort.abort()}}})).then(()=>{if(!stopped)controller.close();return saveQuoteGroups(code,results,env)});ctx?.waitUntil?.(work);},cancel(){stopped=true;abort.abort()}});
