const QUOTE_GROUPS=16;
// Old price files may exist, but public responses only use observations from the current inventory generation.
async function quoteGenerationFloor(env){const object=await env.BUCKET?.get('inventory/state.json');const data=object?await object.json():typeof SNAPSHOT==='undefined'?null:SNAPSHOT;return Date.parse(data?.checkedAt)||0;}
function reusableQuote(q,code){const age=Date.now()-Date.parse(q.checkedAt);return q.code===code&&(!['unavailable','period_unavailable'].includes(q.status)||q.priceChecked===true)&&Number.isFinite(age)&&age>=-60000&&age<24*60*60*1000;}
