async function saveQuoteGroups(code,quotes,env){
 if(!env.BUCKET)return;const groups=new Map();for(const q of quotes){if(q.status==='error'||!reusableQuote(q,code))continue;const group=Number(q.id)%QUOTE_GROUPS;if(!groups.has(group))groups.set(group,[]);groups.get(group).push(q)}
 await Promise.all([...groups].map(async([group,updates])=>{try{const key=quoteGroupKey(code,group);for(let attempt=0;attempt<3;attempt++){
  const object=await env.BUCKET.get(key),old=object?await object.json():[],merged=new Map((Array.isArray(old)?old:[]).filter(q=>q.status!=='error'&&reusableQuote(q,q.code)).map(q=>[q.id+':'+q.code,q]));
  for(const q of updates){const key=q.id+':'+q.code,before=merged.get(key);if(!before||Date.parse(q.checkedAt)>=Date.parse(before.checkedAt))merged.set(key,q)}
  const saved=await env.BUCKET.put(key,JSON.stringify(limitBasis([...merged.values()])),{onlyIf:object?{etagMatches:object.etag}:{etagDoesNotMatch:'*'},httpMetadata:{contentType:'application/json'}});if(saved)return;
 }}catch{}}));
}
async function quoteSnapshotResponse(url,env){
 let conditions;try{conditions=parseConditions(url.searchParams);if(!conditions)throw Error()}catch{return Response.json({error:'Invalid conditions'},{status:400})}
 const code=priceCode(conditions),active=await activeInventoryIds(env),floor=await quoteGenerationFloor(env);if(!env.BUCKET)return Response.json({code,quotes:[]});
 const groups=await Promise.all(Array.from({length:QUOTE_GROUPS},async(_,i)=>{try{const object=await env.BUCKET.get(quoteGroupKey(code,i));if(!object)return [];const data=await object.json();return Array.isArray(data)?data.filter(q=>(!active||active.has(String(q.id)))&&/^\d{1,10}$/.test(String(q.id))&&q.status!=='error'&&Date.parse(q.checkedAt)>=floor&&reusableQuote(q,code)):[]}catch{return []}}));
 return Response.json({code,quotes:groups.flat()},{headers:{'Cache-Control':'no-store'}});
}

// Bound multi-condition history; source quotes only, with CAS merging across visitors.
function limitBasis(quotes){const counts=new Map();return quotes.sort((a,b)=>Number(b.status==='basis_epoch')-Number(a.status==='basis_epoch')||Date.parse(b.checkedAt)-Date.parse(a.checkedAt)).filter(q=>{const id=String(q.id),n=counts.get(id)||0;counts.set(id,n+1);return n<96;});}
